const browser = await chromium.launch({ executablePath: exe, args: ['--no-sandbox'] })
const ctx = await browser.newContext({ viewport:{width:390,height:844}, deviceScaleFactor:2 })
const page = await ctx.newPage()
await page.route('**/*', r=>{const u=r.request().url(); if(/\.(woff2?|ttf|otf)(\?|$)/i.test(u)||/static\.figma\.com\/font/i.test(u))return r.abort(); r.continue()})
await page.goto('http://localhost:8443/',{waitUntil:'domcontentloaded',timeout:30000}); await page.waitForTimeout(1200)
await page.locator('input[type=checkbox]').first().check({timeout:3000}).catch(()=>{})
await page.getByRole('button',{name:'登录',exact:true}).click({timeout:5000}).catch(()=>{})
await page.waitForTimeout(1000); await page.getByText('物业手持端',{exact:false}).first().click({timeout:5000}).catch(()=>{}); await page.waitForTimeout(1000)
await page.evaluate(l=>{const e=[...document.querySelectorAll('button,[role=button],div,span,a')].filter(x=>(x.textContent||'').trim()===l); if(e.length)e[e.length-1].click()},'工作台')
await page.waitForTimeout(1200)
async function dump(tab){
 await page.evaluate(l=>{const e=[...document.querySelectorAll('*')].filter(x=>(x.textContent||'').trim()===l && x.getBoundingClientRect().left<120); if(e.length)e[0].click()}, tab)
 await page.waitForTimeout(800)
 const info = await page.evaluate(()=>{
  const all=[...document.querySelectorAll('body *')]
  const cards=[]
  for(const el of all){
   const r=el.getBoundingClientRect(); const cs=getComputedStyle(el)
   if(r.left<60||r.width<100||r.width>180||r.height<90||r.height>160) continue
   if(!(cs.boxShadow&&cs.boxShadow!=='none')) continue
   // find icon well: element wrapping img with rounded bg
   const img=el.querySelector('img')
   let well=null
   if(img){ let p=img.parentElement; for(let i=0;i<3&&p;i++){ const ps=getComputedStyle(p); const pr=p.getBoundingClientRect(); if(pr.width>=32&&pr.width<=60&&ps.borderRadius!=='0px'){ well={bg:ps.backgroundColor,radius:ps.borderRadius,w:+pr.width.toFixed(0),h:+pr.height.toFixed(0)}; break } p=p.parentElement } }
   // title element font
   const txtEls=[...el.querySelectorAll('*')].filter(e=>(e.textContent||'').trim() && e.children.length===0)
   const titleEl = txtEls[0]
   const tcs = titleEl?getComputedStyle(titleEl):null
   cards.push({ title:(el.textContent||'').trim(), well, titleFont: tcs?{fs:tcs.fontSize,fw:tcs.fontWeight,color:tcs.color}:null })
  }
  const seen=new Set();return cards.filter(c=>{if(seen.has(c.title))return false;seen.add(c.title);return true})
 })
 console.log('TAB',tab); for(const c of info) console.log(JSON.stringify(c))
}
await dump('项目检查'); await dump('防台防汛')
await browser.close()

